-- OWN TRAVEL AND PLANS REHEARSAL (generated from supabase/rehearsal/rehearsal_own_travel.template.sql + the migration by scripts/build-rehearsal.mjs; do not edit this file by hand).
-- ONE batch that applies 20261201090000_own_travel_and_plans.sql, exercises set_my_travel / save_my_plan_item on the private test trip as an organiser, a pending participant, a declined one and a non-member,
-- then ENDS WITH AN ERROR so that EVERYTHING ROLLS BACK. Result: "REHEARSAL PASS [...]" or "REHEARSAL FAIL [...]". Impersonation is claims + SET LOCAL ROLE (authenticated / anon).
-- The people are three EXISTING public.users who are not on the test trip, chosen by query when this runs; two are added to the trip inside the transaction. No name or id is ever printed. Nothing is left behind.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '60s';

CREATE TEMP TABLE _rehearsal (step text, ok boolean, detail text);
CREATE TEMP TABLE _rh_ctx (k text PRIMARY KEY, v text);
CREATE FUNCTION pg_temp.rh_rec(p_step text, p_ok boolean, p_detail text) RETURNS void LANGUAGE sql AS $f$
  INSERT INTO _rehearsal VALUES (p_step, coalesce(p_ok, false), left(p_detail, 400))
$f$;
CREATE FUNCTION pg_temp.rh_ctx(p_k text) RETURNS text LANGUAGE sql STABLE AS $f$
  SELECT v FROM _rh_ctx WHERE k = p_k
$f$;
-- run ONE statement as a signed-in person (p_uid, role authenticated) or as anon (p_uid NULL, p_role anon); a select returns its single jsonb column, anything else just runs.
-- Never raises: {"ok":true,"r":<result>} or {"ok":false,"code":<sqlstate>,"hint":<hint>}
CREATE FUNCTION pg_temp.rh_call(p_uid uuid, p_role text, p_sql text) RETURNS jsonb LANGUAGE plpgsql AS $f$
DECLARE
  v_r jsonb; v_hint text;
BEGIN
  PERFORM set_config('request.jwt.claims', CASE WHEN p_uid IS NULL THEN json_build_object('role', p_role)::text ELSE json_build_object('sub', p_uid, 'role', p_role)::text END, true);
  PERFORM set_config('request.jwt.claim.sub', coalesce(p_uid::text, ''), true);
  PERFORM set_config('request.jwt.claim.role', p_role, true);
  BEGIN
    EXECUTE format('SET LOCAL ROLE %I', p_role);
    IF p_sql ~* '^\s*select' THEN EXECUTE p_sql INTO v_r; ELSE EXECUTE p_sql; END IF;
    RESET ROLE;
    RETURN jsonb_build_object('ok', true, 'r', v_r);
  EXCEPTION WHEN OTHERS THEN
    GET STACKED DIAGNOSTICS v_hint = PG_EXCEPTION_HINT;
    RESET ROLE;
    RETURN jsonb_build_object('ok', false, 'code', SQLSTATE, 'hint', v_hint);
  END;
END
$f$;

-- ===== 0a. BEFORE: the names are free and the helpers are there ================================================================================================
DO $rh$
DECLARE
  v_n integer;
BEGIN
  BEGIN
    SELECT count(*) INTO v_n FROM pg_proc WHERE pronamespace = 'public'::regnamespace AND proname IN ('set_my_travel', 'save_my_plan_item', '_own_travel_date');
    PERFORM pg_temp.rh_rec('pre.names_free', v_n = 0, 'functions absent: ' || v_n);
    PERFORM pg_temp.rh_rec('pre.policies', (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'trip_timeline_events') = 4
      AND (SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'trip_timeline_events' AND cmd IN ('INSERT', 'UPDATE', 'DELETE') AND policyname LIKE 'organizers\_%\_timeline') = 3,
      'the four organiser / participant policies are there');
    INSERT INTO _rh_ctx VALUES ('policies0', (SELECT string_agg(policyname || ':' || cmd || ':' || coalesce(qual, '') || ':' || coalesce(with_check, ''), '|' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'trip_timeline_events'));
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('pre', false, 'ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
END
$rh$;

-- ===== BEGIN MIGRATION (verbatim copy of supabase/migrations/20261201090000_own_travel_and_plans.sql) =====
@@MIGRATION@@
-- ===== END MIGRATION =====

-- ===== 0b. the people ===========================================================================================================================================
-- Three EXISTING public.users who are not on the test trip are picked by query at run time (never named or printed): O becomes its organiser, B a pending participant, C stays a non-member.
-- They are added to the trip INSIDE this transaction by cloning an existing participant row of the trip (as in the chat-settings rehearsal); everything rolls back at the end.
DO $rh$
DECLARE
  v_trip constant uuid := 'be551bc4-a524-4b6a-a0c9-b74a7168ced4';
  v_ids uuid[]; v_start date; v_end date; v_n integer; v_cnt_n integer; v_cnt_a integer;
BEGIN
  BEGIN
    SELECT t.start_date, t.end_date INTO v_start, v_end FROM public.trips t WHERE t.id = v_trip;
    IF NOT FOUND THEN PERFORM pg_temp.rh_rec('setup.trip', false, 'test trip not found'); RETURN; END IF;
    IF v_start IS NULL OR v_end IS NULL THEN PERFORM pg_temp.rh_rec('setup.trip', false, 'the test trip has no start or end date'); RETURN; END IF;
    SELECT count(*) INTO v_cnt_n FROM public.notifications;
    SELECT count(*) INTO v_cnt_a FROM public.activity_feed;
    INSERT INTO _rh_ctx VALUES ('notif0', v_cnt_n::text), ('act0', v_cnt_a::text), ('trip', v_trip::text), ('start', v_start::text), ('end', v_end::text);
    SELECT array_agg(x.id) INTO v_ids FROM (SELECT u.id FROM public.users u WHERE NOT EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = u.id) ORDER BY (u.role::text = 'admin'), u.id LIMIT 3) x;
    v_n := coalesce(array_length(v_ids, 1), 0);
    IF v_n < 3 THEN
      PERFORM pg_temp.rh_rec('setup.people', false, format('need 3 existing users who are not on the test trip to act as organiser, participant and non-member; found %s', v_n));
      RETURN;
    END IF;
    FOR v_n IN 1..2 LOOP
      INSERT INTO public.trip_participants (trip_id, user_id, role, confirmation_status) VALUES (v_trip, v_ids[v_n], (CASE WHEN v_n = 1 THEN 'organizer' ELSE 'participant' END)::public.participant_role, 'pending');
    END LOOP;
    INSERT INTO _rh_ctx VALUES ('org', v_ids[1]::text), ('mem', v_ids[2]::text), ('out', v_ids[3]::text);
    PERFORM pg_temp.rh_rec('setup.people', EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = v_ids[1] AND tp.role::text = 'organizer' AND tp.active AND tp.confirmation_status::text = 'pending')
      AND EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = v_ids[2] AND tp.role::text <> 'organizer' AND tp.active AND tp.confirmation_status::text = 'pending')
      AND NOT EXISTS (SELECT 1 FROM public.trip_participants tp WHERE tp.trip_id = v_trip AND tp.user_id = v_ids[3]),
      'organiser and pending participant added to the test trip inside the transaction; a third user left off it (no names or ids shown)');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('setup.people', false, 'ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
END
$rh$;

CREATE FUNCTION pg_temp.rh_own(p_uid uuid) RETURNS uuid[] LANGUAGE sql STABLE AS $f$
  SELECT COALESCE(array_agg(e.id), '{}') FROM public.trip_timeline_events e
   WHERE e.trip_id = pg_temp.rh_ctx('trip')::uuid AND e.participant_ids = ARRAY[p_uid] AND e.source_option_id IS NULL AND public._own_is_travel(e.metadata)
$f$;

-- ===== 1. structure ===========================================================================================================================================
DO $rh$
DECLARE
  v_bad text := ''; r record;
BEGIN
  BEGIN
    FOR r IN SELECT * FROM (VALUES ('public.set_my_travel(uuid,jsonb,uuid[])', true), ('public.save_my_plan_item(uuid,uuid,jsonb)', true), ('public._own_travel_date(text)', false)) AS x(f, want_auth) LOOP
      IF has_function_privilege('anon', r.f, 'EXECUTE') OR has_function_privilege('authenticated', r.f, 'EXECUTE') IS DISTINCT FROM r.want_auth THEN v_bad := v_bad || r.f || ' '; END IF;
    END LOOP;
    PERFORM pg_temp.rh_rec('struct.function_privileges', v_bad = '', CASE WHEN v_bad = '' THEN 'the 2 RPCs: authenticated only (not anon); the helper: nobody' ELSE 'wrong: ' || v_bad END);
    PERFORM pg_temp.rh_rec('struct.definer', (SELECT count(*) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('set_my_travel', 'save_my_plan_item') AND p.prosecdef AND p.provolatile = 'v' AND p.proconfig::text LIKE '%search_path%') = 2,
      'SECURITY DEFINER, VOLATILE, pinned search_path');
    PERFORM pg_temp.rh_rec('struct.policies_unchanged', (SELECT string_agg(policyname || ':' || cmd || ':' || coalesce(qual, '') || ':' || coalesce(with_check, ''), '|' ORDER BY policyname) FROM pg_policies WHERE schemaname = 'public' AND tablename = 'trip_timeline_events') IS NOT DISTINCT FROM pg_temp.rh_ctx('policies0'),
      'the table policies are exactly as before the migration');
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_temp.rh_rec('struct', false, 'ERROR ' || SQLSTATE || ' ' || left(SQLERRM, 80));
  END;
END
$rh$;

-- ===== 2. behaviour ===========================================================================================================================================
DO $rh$
DECLARE
  v_trip uuid := pg_temp.rh_ctx('trip')::uuid; v_org uuid := pg_temp.rh_ctx('org')::uuid; v_mem uuid := pg_temp.rh_ctx('mem')::uuid; v_out uuid := pg_temp.rh_ctx('out')::uuid;
  v_s date := pg_temp.rh_ctx('start')::date; v_e date := pg_temp.rh_ctx('end')::date; v_t text; v_r jsonb; v_legs jsonb; v_first text; v_n integer;
  v_arr uuid; v_dep uuid; v_ext uuid; v_orow uuid; v_group uuid; v_orgplan uuid; v_brow uuid; v_known uuid[]; v_item uuid; v_title text; v_before text; v_cat text; v_meta jsonb;
BEGIN
  IF v_org IS NULL OR v_mem IS NULL OR v_out IS NULL OR v_s IS NULL THEN RETURN; END IF;
  v_t := quote_literal(v_trip);
  SELECT coalesce(NULLIF(btrim(u.first_name), ''), NULLIF(split_part(btrim(coalesce(u.full_name, '')), ' ', 1), ''), 'Someone') INTO v_first FROM public.users u WHERE u.id = v_mem;
  -- rows other people own (made by the owner role, no JWT): O's own travel row, an organiser group event, an organiser plan row for O alone
  INSERT INTO public.trip_timeline_events (trip_id, event_date, title, category, participant_ids, metadata, created_by) VALUES (v_trip, v_s, 'rh O travel', 'transfer', ARRAY[v_org], '{"travel_details":true,"direction":"arrival"}', v_org) RETURNING id INTO v_orow;
  INSERT INTO public.trip_timeline_events (trip_id, event_date, title, category, participant_ids, metadata, created_by) VALUES (v_trip, v_s, 'rh group event', 'activity', NULL, '{}', v_org) RETURNING id INTO v_group;
  INSERT INTO public.trip_timeline_events (trip_id, event_date, title, category, participant_ids, metadata, created_by) VALUES (v_trip, v_s, 'rh O plan', 'dining', ARRAY[v_org], '{}', v_org) RETURNING id INTO v_orgplan;

  -- 1. B saves an arrival 2 days before the trip and a departure 2 days after it
  v_legs := jsonb_build_array(
    jsonb_build_object('direction', 'arrival', 'leg', 'main', 'date', v_s - 2, 'time', '10:00', 'flight_ref', ' JL044 ', 'airport_code', 'lhr', 'set_off_date', v_s - 3, 'set_off_time', '21:00'),
    jsonb_build_object('direction', 'departure', 'leg', 'main', 'date', v_e + 2, 'time', '01:55'));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, v_legs::text, pg_temp.rh_own(v_mem)));
  v_arr := (SELECT (x ->> 'id')::uuid FROM jsonb_array_elements(v_r #> '{r,legs}') x WHERE x ->> 'direction' = 'arrival');
  v_dep := (SELECT (x ->> 'id')::uuid FROM jsonb_array_elements(v_r #> '{r,legs}') x WHERE x ->> 'direction' = 'departure');
  SELECT e.title, e.category::text, e.metadata INTO v_title, v_cat, v_meta FROM public.trip_timeline_events e WHERE e.id = v_arr;
  PERFORM pg_temp.rh_rec('1.member_saves_outside_dates', (v_r ->> 'ok')::boolean AND jsonb_array_length(v_r #> '{r,legs}') = 2 AND v_arr IS NOT NULL AND v_dep IS NOT NULL
      AND v_title = v_first || ' arrives' AND v_cat = 'flight' AND v_meta = jsonb_build_object('travel_details', true, 'direction', 'arrival', 'leg', 'main', 'flight_ref', 'JL044', 'airport_code', 'LHR', 'set_off_date', (v_s - 3)::text, 'set_off_time', '21:00')
      AND (SELECT count(*) FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.metadata ->> 'travel_details' = 'true' AND e.participant_ids = ARRAY[v_mem] AND e.created_by = v_mem) = 2
      AND (SELECT e.title FROM public.trip_timeline_events e WHERE e.id = v_dep) = v_first || ' departs' AND (SELECT e.event_date FROM public.trip_timeline_events e WHERE e.id = v_dep) = v_e + 2,
    'start-2 arrival and end+2 departure saved; title from the first name; participant_ids = [caller]; metadata built from validated fields');

  -- 2. an extra leg 6 days before the trip (the existing legs are sent back with their ids)
  v_legs := jsonb_build_array(
    jsonb_build_object('id', v_arr, 'direction', 'arrival', 'leg', 'main', 'date', v_s - 2, 'time', '10:00', 'flight_ref', 'JL044', 'airport_code', 'LHR', 'set_off_date', v_s - 3, 'set_off_time', '21:00'),
    jsonb_build_object('id', v_dep, 'direction', 'departure', 'leg', 'main', 'date', v_e + 2, 'time', '01:55'),
    jsonb_build_object('direction', 'arrival', 'leg', 'extra', 'title', 'Flight to Tokyo', 'date', v_s - 6));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, v_legs::text, pg_temp.rh_own(v_mem)));
  v_ext := (SELECT (x ->> 'id')::uuid FROM jsonb_array_elements(v_r #> '{r,legs}') x WHERE x ->> 'leg' = 'extra');
  PERFORM pg_temp.rh_rec('2.extra_leg_start_minus_6', (v_r ->> 'ok')::boolean AND v_ext IS NOT NULL AND (v_r #>> '{r,legs,0,id}')::uuid = v_arr AND (v_r #>> '{r,legs,1,id}')::uuid = v_dep
      AND (SELECT e.event_date = v_s - 6 AND e.all_day AND e.category::text = 'transport' AND e.title = 'Flight to Tokyo' FROM public.trip_timeline_events e WHERE e.id = v_ext)
      AND (SELECT count(*) FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.metadata ->> 'travel_details' = 'true' AND e.participant_ids = ARRAY[v_mem]) = 3,
    'ids kept, extra leg added, all-day, category transport');

  -- 3. saving without the departure deletes it
  v_legs := jsonb_build_array(
    jsonb_build_object('id', v_arr, 'direction', 'arrival', 'leg', 'main', 'date', v_s - 2, 'time', '10:00', 'flight_ref', 'JL044', 'airport_code', 'LHR'),
    jsonb_build_object('id', v_ext, 'direction', 'arrival', 'leg', 'extra', 'title', 'Flight to Tokyo', 'date', v_s - 6));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, v_legs::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('3.omitted_leg_deleted', (v_r ->> 'ok')::boolean AND NOT EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.id = v_dep)
      AND (SELECT count(*) FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.metadata ->> 'travel_details' = 'true' AND e.participant_ids = ARRAY[v_mem]) = 2
      AND NOT (SELECT e.metadata ? 'set_off_date' FROM public.trip_timeline_events e WHERE e.id = v_arr), 'the departure is gone; the arrival lost its cleared set-off');

  -- 4. someone else's rows by id: bad_id, and the rows are untouched
  v_legs := jsonb_build_array(jsonb_build_object('id', v_orow, 'direction', 'arrival', 'leg', 'main', 'date', v_s));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, v_legs::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('4.other_persons_travel_row', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'bad_id' AND v_r ->> 'code' = '22023' AND (SELECT e.title FROM public.trip_timeline_events e WHERE e.id = v_orow) = 'rh O travel', coalesce(v_r ->> 'hint', ''));
  v_legs := jsonb_build_array(jsonb_build_object('id', v_group, 'direction', 'arrival', 'leg', 'main', 'date', v_s));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, v_legs::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('4b.group_event_by_id', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'bad_id' AND (SELECT e.title FROM public.trip_timeline_events e WHERE e.id = v_group) = 'rh group event', coalesce(v_r ->> 'hint', ''));
  PERFORM pg_temp.rh_rec('4c.nothing_of_others_deleted', (SELECT count(*) FROM public.trip_timeline_events e WHERE e.id IN (v_orow, v_group, v_orgplan)) = 3, 'a refused or a successful save never deletes rows that are not the caller''s own');

  -- 5. a date in the wrong year; the other shape rules
  v_legs := jsonb_build_array(jsonb_build_object('direction', 'arrival', 'leg', 'main', 'date', v_s + 400));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, v_legs::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('5.wrong_year', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'bad_date', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, jsonb_build_array(jsonb_build_object('direction', 'arrival', 'date', v_s, 'user_id', v_org))::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('5b.unknown_key_rejected', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'bad_legs', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, jsonb_build_array(jsonb_build_object('direction', 'arrival', 'date', v_s, 'time', '25:00'))::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('5c.bad_time', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'bad_time', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, jsonb_build_array(jsonb_build_object('direction', 'arrival', 'date', v_s), jsonb_build_object('direction', 'arrival', 'date', v_s + 1))::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('5d.two_main_legs', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'too_many', coalesce(v_r ->> 'hint', ''));

  -- 6. a non-member and an anonymous caller
  v_r := pg_temp.rh_call(v_out, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, jsonb_build_array(jsonb_build_object('direction', 'arrival', 'date', v_s))::text, pg_temp.rh_own(v_out)));
  PERFORM pg_temp.rh_rec('6.non_member', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_participant' AND v_r ->> 'code' = '42501', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(NULL, 'anon', format('select public.set_my_travel(%s, ''[]''::jsonb, %L::uuid[])', v_t, NULL::uuid[]));
  PERFORM pg_temp.rh_rec('6b.anon', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'code' = '42501', coalesce(v_r ->> 'code', ''));
  v_r := pg_temp.rh_call(v_out, 'authenticated', format('select public.save_my_plan_item(%s, NULL, %L::jsonb)', v_t, jsonb_build_object('title', 'x', 'date', v_s)::text));
  PERFORM pg_temp.rh_rec('6c.non_member_plan', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_participant', coalesce(v_r ->> 'hint', ''));


  -- 8. direct writes by B are still refused by RLS (insert raises; update and delete touch no row)
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('insert into public.trip_timeline_events (trip_id, event_date, title, created_by, participant_ids) values (%s, %L, ''rh direct'', %L, ARRAY[%L::uuid])', v_t, v_s, v_mem, v_mem));
  PERFORM pg_temp.rh_rec('8.direct_insert_refused', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'code' = '42501' AND NOT EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.title = 'rh direct'), coalesce(v_r ->> 'code', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('update public.trip_timeline_events set title = ''rh hacked'' where trip_id = %s', v_t));
  PERFORM pg_temp.rh_rec('8b.direct_update_refused', NOT EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.title = 'rh hacked'), 'no row changed');
  v_before := (SELECT count(*) FROM public.trip_timeline_events WHERE trip_id = v_trip)::text;
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('delete from public.trip_timeline_events where trip_id = %s', v_t));
  PERFORM pg_temp.rh_rec('8c.direct_delete_refused', (SELECT count(*) FROM public.trip_timeline_events WHERE trip_id = v_trip)::text = v_before, 'no row deleted');

  -- 9. the organiser makes a travel row for B directly; B's RPC updates it and then clears it
  v_known := pg_temp.rh_own(v_mem);
  v_r := pg_temp.rh_call(v_org, 'authenticated', format('insert into public.trip_timeline_events (trip_id, event_date, title, category, participant_ids, metadata, created_by) values (%s, %L, ''rh made for B'', ''flight'', ARRAY[%L::uuid], ''{"travel_details":true,"direction":"departure"}'', %L)', v_t, v_e, v_mem, v_org));
  SELECT e.id INTO v_brow FROM public.trip_timeline_events e WHERE e.title = 'rh made for B';
  PERFORM pg_temp.rh_rec('9a.organiser_direct_insert', (v_r ->> 'ok')::boolean AND v_brow IS NOT NULL, 'the organiser''s own direct insert still works (also step 12)');
  -- stale guard: B "loaded" before the organiser added the row (v_known is the older list), so a replace-set call is refused and nothing is deleted
  SELECT count(*) INTO v_n FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.participant_ids = ARRAY[v_mem];
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, ''[]''::jsonb, %L::uuid[])', v_t, v_known));
  PERFORM pg_temp.rh_rec('9s.stale_after_organiser_added_a_row', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'stale' AND v_r ->> 'code' = '55000'
      AND (SELECT count(*) FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.participant_ids = ARRAY[v_mem]) = v_n AND EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.id = v_brow), coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, ''[]''::jsonb, ''{}''::uuid[])', v_t));
  PERFORM pg_temp.rh_rec('9t.empty_known_ids_with_rows', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'stale' AND (SELECT count(*) FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.participant_ids = ARRAY[v_mem]) = v_n, 'empty legs and empty known ids while rows exist: refused, rows intact');
  v_legs := jsonb_build_array(
    jsonb_build_object('id', v_arr, 'direction', 'arrival', 'leg', 'main', 'date', v_s - 2),
    jsonb_build_object('id', v_ext, 'direction', 'arrival', 'leg', 'extra', 'title', 'Flight to Tokyo', 'date', v_s - 6),
    jsonb_build_object('id', v_brow, 'direction', 'departure', 'leg', 'main', 'date', v_e + 1, 'time', '09:30'));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, %L::jsonb, %L::uuid[])', v_t, v_legs::text, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('9b.updates_organiser_made_row', (v_r ->> 'ok')::boolean AND (SELECT e.event_date = v_e + 1 AND e.title = v_first || ' departs' AND e.created_by = v_org AND e.participant_ids = ARRAY[v_mem] FROM public.trip_timeline_events e WHERE e.id = v_brow), 'updated in place; still created by the organiser');
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, ''[]''::jsonb, %L::uuid[])', v_t, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('9c.clears_all_own_travel', (v_r ->> 'ok')::boolean AND jsonb_array_length(v_r #> '{r,legs}') = 0 AND NOT EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.participant_ids = ARRAY[v_mem])
      AND (SELECT count(*) FROM public.trip_timeline_events e WHERE e.id IN (v_orow, v_group, v_orgplan)) = 3, 'an empty list removes every own travel row and nothing else');

  -- 10. B's own plan item: insert, update, delete
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, NULL, %L::jsonb)', v_t, jsonb_build_object('title', ' Dinner in Tokyo ', 'date', v_s - 4, 'start_time', '19:30', 'notes', 'table for two', 'category', 'dining', 'location', 'Shibuya')::text));
  v_item := (v_r #>> '{r,id}')::uuid;
  PERFORM pg_temp.rh_rec('10a.plan_insert', (v_r ->> 'ok')::boolean AND v_item IS NOT NULL AND (SELECT e.title = 'Dinner in Tokyo' AND e.event_date = v_s - 4 AND e.start_time = '19:30' AND NOT e.all_day AND e.description = 'table for two' AND e.category::text = 'dining'
      AND e.participant_ids = ARRAY[v_mem] AND e.created_by = v_mem AND e.source_option_id IS NULL AND e.metadata = '{}' FROM public.trip_timeline_events e WHERE e.id = v_item), 'inserted as "just me", 4 days before the trip');
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, %L, %L::jsonb)', v_t, v_item, jsonb_build_object('title', 'Late dinner', 'date', v_s - 4, 'start_time', '20:30', 'end_time', '22:00')::text));
  PERFORM pg_temp.rh_rec('10b.plan_update', (v_r ->> 'ok')::boolean AND (v_r #>> '{r,id}')::uuid = v_item AND (SELECT e.title = 'Late dinner' AND e.end_time = '22:00' AND e.description IS NULL AND e.participant_ids = ARRAY[v_mem] FROM public.trip_timeline_events e WHERE e.id = v_item), 'updated in place');
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, %L, NULL)', v_t, v_item));
  PERFORM pg_temp.rh_rec('10c.plan_delete', (v_r ->> 'ok')::boolean AND NOT EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.id = v_item), 'deleted');

  -- 11. B tries the organiser's plan rows, a group event and travel rows through the plan RPC: not_yours
  v_n := 0;
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, %L, %L::jsonb)', v_t, v_orgplan, jsonb_build_object('title', 'mine now', 'date', v_s)::text));
  PERFORM pg_temp.rh_rec('11a.update_organiser_plan', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_yours' AND (SELECT e.title FROM public.trip_timeline_events e WHERE e.id = v_orgplan) = 'rh O plan', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, %L, %L::jsonb)', v_t, v_group, jsonb_build_object('title', 'mine now', 'date', v_s)::text));
  PERFORM pg_temp.rh_rec('11b.update_group_event', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_yours' AND (SELECT e.title FROM public.trip_timeline_events e WHERE e.id = v_group) = 'rh group event', coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, %L, NULL)', v_t, v_group));
  PERFORM pg_temp.rh_rec('11c.delete_group_event', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_yours' AND EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.id = v_group), coalesce(v_r ->> 'hint', ''));
  -- a travel row of B's own is not a plan item either
  INSERT INTO public.trip_timeline_events (trip_id, event_date, title, category, participant_ids, metadata, created_by) VALUES (v_trip, v_s, 'rh B travel', 'flight', ARRAY[v_mem], '{"travel_details":true,"direction":"arrival"}', v_mem) RETURNING id INTO v_item;
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, %L, NULL)', v_t, v_item));
  PERFORM pg_temp.rh_rec('11d.own_travel_row_is_not_a_plan_item', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_yours' AND EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.id = v_item), coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, NULL, %L::jsonb)', v_t, jsonb_build_object('title', 'x', 'date', v_s, 'participant_ids', jsonb_build_array(v_org))::text));
  PERFORM pg_temp.rh_rec('11e.cannot_set_participants', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'bad_item', coalesce(v_r ->> 'hint', ''));

  -- 12. the organiser's direct insert and update still work
  v_r := pg_temp.rh_call(v_org, 'authenticated', format('insert into public.trip_timeline_events (trip_id, event_date, title, created_by) values (%s, %L, ''rh organiser direct'', %L)', v_t, v_s, v_org));
  PERFORM pg_temp.rh_rec('12.organiser_direct_insert', (v_r ->> 'ok')::boolean AND EXISTS (SELECT 1 FROM public.trip_timeline_events e WHERE e.title = 'rh organiser direct'), coalesce(v_r ->> 'code', ''));
  v_r := pg_temp.rh_call(v_org, 'authenticated', format('update public.trip_timeline_events set title = ''rh O plan 2'' where id = %L', v_orgplan));
  PERFORM pg_temp.rh_rec('12b.organiser_direct_update', (v_r ->> 'ok')::boolean AND (SELECT e.title FROM public.trip_timeline_events e WHERE e.id = v_orgplan) = 'rh O plan 2', coalesce(v_r ->> 'code', ''));
  -- 14. LAST: B no longer active, then B declined (the only status change; never to 'confirmed', never set back). B keeps one travel row to prove a refused call deletes nothing.
  INSERT INTO public.trip_timeline_events (trip_id, event_date, title, category, participant_ids, metadata, created_by) VALUES (v_trip, v_s, 'rh B travel 2', 'flight', ARRAY[v_mem], '{"travel_details":true,"direction":"arrival"}', v_mem);
  UPDATE public.trip_participants SET active = false WHERE trip_id = v_trip AND user_id = v_mem;
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, ''[]''::jsonb, %L::uuid[])', v_t, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('7c.inactive', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_participant', coalesce(v_r ->> 'hint', ''));
  UPDATE public.trip_participants SET active = true WHERE trip_id = v_trip AND user_id = v_mem;
  UPDATE public.trip_participants SET confirmation_status = 'declined' WHERE trip_id = v_trip AND user_id = v_mem;
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.set_my_travel(%s, ''[]''::jsonb, %L::uuid[])', v_t, pg_temp.rh_own(v_mem)));
  PERFORM pg_temp.rh_rec('7.declined', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_participant' AND (SELECT count(*) FROM public.trip_timeline_events e WHERE e.trip_id = v_trip AND e.participant_ids = ARRAY[v_mem]) = 2, coalesce(v_r ->> 'hint', ''));
  v_r := pg_temp.rh_call(v_mem, 'authenticated', format('select public.save_my_plan_item(%s, NULL, %L::jsonb)', v_t, jsonb_build_object('title', 'x', 'date', v_s)::text));
  PERFORM pg_temp.rh_rec('7b.declined_plan', NOT (v_r ->> 'ok')::boolean AND v_r ->> 'hint' = 'not_participant', coalesce(v_r ->> 'hint', ''));
END
$rh$;

-- ===== side effects: the temporary people and the calls above sent nothing ==================================================================================
DO $rh$
DECLARE
  v_n integer; v_a integer;
BEGIN
  IF pg_temp.rh_ctx('notif0') IS NULL THEN PERFORM pg_temp.rh_rec('side_effects.no_notifications', false, 'no baseline (setup did not run)'); RETURN; END IF;
  SELECT count(*) INTO v_n FROM public.notifications;
  SELECT count(*) INTO v_a FROM public.activity_feed;
  PERFORM pg_temp.rh_rec('side_effects.no_notifications', v_n = pg_temp.rh_ctx('notif0')::integer, format('notifications before=%s now=%s (the database never sends mail)', pg_temp.rh_ctx('notif0'), v_n));
  PERFORM pg_temp.rh_rec('side_effects.no_activity_rows', v_a = pg_temp.rh_ctx('act0')::integer, format('activity_feed before=%s now=%s (the two functions write none)', pg_temp.rh_ctx('act0'), v_a));
END
$rh$;

-- ===== FINAL: report through the error message (this also rolls everything back) ===============================================================================
DO $rh$
DECLARE
  v_all boolean; v_json text; v_failed integer; v_total integer;
BEGIN
  SELECT coalesce(bool_and(ok), false), count(*) FILTER (WHERE NOT ok), count(*) INTO v_all, v_failed, v_total FROM _rehearsal;
  SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 160)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, CASE WHEN ok THEN 0 ELSE 90 END)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal;
  END IF;
  IF length(v_json) > 6000 THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object('step', step, 'ok', ok, 'detail', left(detail, 90)) ORDER BY ok, ctid), '[]'::jsonb)::text INTO v_json FROM _rehearsal WHERE NOT ok;
    v_json := left(v_json, 5800) || ' (only failing steps shown)';
  END IF;
  RAISE EXCEPTION '%', 'REHEARSAL ' || CASE WHEN v_all THEN 'PASS' ELSE 'FAIL' END || ' (' || v_total || ' steps, ' || v_failed || ' failed) ' || v_json;
END
$rh$;
ROLLBACK;
